var WORK_MINUTES = (ctx.config && Number(ctx.config.workMinutes)) || 25;
var state = { remaining: WORK_MINUTES * 60, intervalId: null };
// Stash mutable state on ctx so teardownJs (which receives the same
// ctx object) can clear the interval.
ctx._pomodoro = state;

var widget = document.createElement('div');
widget.className = 'plugin-pomodoro';
var display = document.createElement('span');
display.className = 'plugin-pomodoro-time';
var toggle = document.createElement('button');
toggle.className = 'btn';
toggle.textContent = 'Start';
var reset = document.createElement('button');
reset.className = 'btn';
reset.textContent = 'Reset';
widget.appendChild(display);
widget.appendChild(toggle);
widget.appendChild(reset);
ctx.api.ui.inject('.header', widget, 'append');

function paint() {
  var m = Math.floor(state.remaining / 60);
  var s = state.remaining % 60;
  display.textContent = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
}

function stopTimer() {
  toggle.textContent = 'Start';
  if (state.intervalId) {
    clearInterval(state.intervalId);
    state.intervalId = null;
  }
}

async function finish() {
  stopTimer();
  state.remaining = WORK_MINUTES * 60;
  paint();
  ctx.api.ui.showToast('Pomodoro complete — take a break!', 'success');
  var done = (await ctx.api.storage.get('completed')) || 0;
  await ctx.api.storage.set('completed', done + 1);
}

function tick() {
  state.remaining -= 1;
  if (state.remaining <= 0) { finish(); return; }
  paint();
}

function startTimer() {
  toggle.textContent = 'Pause';
  state.intervalId = setInterval(tick, 1000);
}

toggle.onclick = function() { state.intervalId ? stopTimer() : startTimer(); };
reset.onclick = function() { stopTimer(); state.remaining = WORK_MINUTES * 60; paint(); };
paint();

ctx.api.storage.get('completed').then(function(done) {
  if (done) ctx.logger.info('Pomodoros completed so far: ' + done);
});
